window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-131"]=[{"id":"set2-F8nQCz36","fingerprint":"5c268b03d9d65371","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care este definiția ocluziei deschise?","options":[{"id":"A","text":"Existența unui spațiu de inocluzie verticală în momentul intercuspidării maxime."},{"id":"B","text":"Anomalia denumită de școala germană „mordex apertus”."},{"id":"C","text":"O entitate distinctă, încadrată întotdeauna în clasa a II-a Angle."},{"id":"D","text":"O anomalie definită exclusiv prin contactul prematur al dinților posteriori."},{"id":"E","text":"Lipsa contactului dintre dinții superiori și inferiori, fără existența unei supraacoperiri în plan vertical."}],"correct":["A","E"],"pages":[512],"source":"set-2"},{"id":"set2-_-iPzfSD","fingerprint":"ef55e2611be76859","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Cum este încadrată ocluzia deschisă în diverse sisteme de clasificare?","options":[{"id":"A","text":"Ocluzia deschisă totală este întotdeauna încadrată în clasa a III-a Angle."},{"id":"B","text":"Carabelli a denumit-o „mordex apertus”."},{"id":"C","text":"În clasificarea școlii germane, se regăsește sub numele de sindromului de ocluzie deschisă."},{"id":"D","text":"În clasificarea clinico-antropologică (Firu), este încadrată în grupa dizarmoniilor dento-alveolare cu modificări în plan sagital."},{"id":"E","text":"În clasificarea lui Angle, apare ca o entitate distinctă în clasa I."}],"correct":["B","C"],"pages":[512],"source":"set-2"},{"id":"set2-AmIlw33d","fingerprint":"ff23819d834a34c6","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații despre epidemiologia ocluziei deschise sunt corecte?","options":[{"id":"A","text":"Frecvența înregistrată în România este de aproximativ 2-3%."},{"id":"B","text":"Incidența ocluziei deschise anterioare variază în funcție de rasă și grupa de vârstă."},{"id":"C","text":"Anomalia are o tendință redusă de autocorecție în perioada dentiției mixte."},{"id":"D","text":"Sexul feminin este mai frecvent afectat de ocluzia deschisă."},{"id":"E","text":"Incidența ocluziei deschise la copii crește odată cu vârsta."}],"correct":["A","B"],"pages":[512],"source":"set-2"},{"id":"set2-6Q_85tjL","fingerprint":"fc109b6edd0c5208","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce caracteristici descriu ocluzia deschisă totală, conform clasificării lui Boboc (1971)?","options":[{"id":"A","text":"Factorii etiologici incriminați sunt predominant cei dismetabolici sau genetici."},{"id":"B","text":"Este caracterizată prin modificări severe la nivelul structurilor osoase și ocluziei."},{"id":"C","text":"Prezintă modificări de amploare mică la nivelul dinților și structurilor osoase."},{"id":"D","text":"Este forma gravă a ocluziei deschise."},{"id":"E","text":"Are drept cauză principală factorii locali, precum interpozițiile."}],"correct":["A","B","D"],"pages":[512],"source":"set-2"},{"id":"set2-bBlTSU7_","fingerprint":"5a301edb6ad2ba37","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt particularitățile ocluziei deschise parțiale, conform clasificării lui Boboc (1971)?","options":[{"id":"A","text":"Este determinată în principal de factori generali, precum cei genetici."},{"id":"B","text":"Se caracterizează prin modificări severe la nivelul ocluziei."},{"id":"C","text":"Prezintă modificări de amploare mult mai mică la nivelul dinților și structurilor osoase."},{"id":"D","text":"Interpozițiile sunt o cauză principală în etiologia sa."},{"id":"E","text":"Este considerată forma mai puțin gravă a acestei anomalii."}],"correct":["C","D","E"],"pages":[512],"source":"set-2"},{"id":"set2-ikU83Xmp","fingerprint":"36699f9ab59d8eac","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce elemente caracterizează ocluzia deschisă anterioară (frontală)?","options":[{"id":"A","text":"Este forma clinică cel mai rar întâlnită."},{"id":"B","text":"Infraocluzia poate afecta zona anterioară maxilară, mandibulară sau ambele."},{"id":"C","text":"Spațiul de inocluzie verticală este situat anterior, în timp ce dinții laterali sunt în contact."},{"id":"D","text":"Poate avea o etiologie dentară, determinată de tulburări ale erupției, sau scheletică."},{"id":"E","text":"Implică întotdeauna atât zona incisivă, cât și zona caninilor."}],"correct":["B","C","D"],"pages":[512],"source":"set-2"},{"id":"set2-6B09JW4W","fingerprint":"536812391a1c47f8","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la ocluzia deschisă posterioară, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Acest tip de malocluzie este întotdeauna bilateral și simetric."},{"id":"B","text":"Se caracterizează prin imposibilitatea dinților laterali de a ajunge în ocluzie, deși există contact dentar anterior."},{"id":"C","text":"Poate fi cauzată de interpoziția limbii sau a obrazului."},{"id":"D","text":"Este o formă de malocluzie frecvent întâlnită în practica clinică."},{"id":"E","text":"Tulburările de erupție, precum anchiloza, pot fi un factor etiologic."}],"correct":["B","C","E"],"pages":[512],"source":"set-2"},{"id":"set2-c4ymk6Z5","fingerprint":"a758afcf9c3c8434","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care sunt caracteristicile ocluziei deschise anterioare de tranziție?","options":[{"id":"A","text":"Este cauzată de interpunerea policelui între arcadele dentare."},{"id":"B","text":"Corecția sa necesită un tratament chirurgical local."},{"id":"C","text":"Se asociază cu afecțiuni precum acondroplazia."},{"id":"D","text":"Este considerată o anomalie persistentă dacă nu este interceptată la timp."},{"id":"E","text":"Apare frecvent la dinții permanenți în erupție."}],"correct":["E"],"pages":[513],"source":"set-2"},{"id":"set2-BFBdajFM","fingerprint":"c7d5554836e3486a","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce definește ocluzia deschisă complexă în clasificarea lui Moyer?","options":[{"id":"A","text":"Este sinonimă cu ocluzia deschisă de tranziție."},{"id":"B","text":"Problema principală este dificultatea dinților de a stabili contacte în plan transversal."},{"id":"C","text":"Este cauzată de o displazie verticală primară."},{"id":"D","text":"Se asociază exclusiv cu malocluzia de Clasa a III-a."},{"id":"E","text":"Este limitată la dinți și procesul alveolar."}],"correct":["C"],"pages":[513],"source":"set-2"},{"id":"set2-Cnk0LLSd","fingerprint":"7af96f39ef9f9b02","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele caracteristici sunt asociate cu ocluzia deschisă scheletică sau adevărată?","options":[{"id":"A","text":"Un tipar cranio-facial situat în limite normale."},{"id":"B","text":"Valori crescute ale unghiului mandibular."},{"id":"C","text":"Un ram ascendent scurt al mandibulei."},{"id":"D","text":"Un tipar facial hiperdivergent."},{"id":"E","text":"Infrapoziția și vestibulo-înclinarea dinților anteriori ca unice modificări."}],"correct":["B","C","D"],"pages":[513],"source":"set-2"},{"id":"set2-HLiiQj2y","fingerprint":"aa3a7ad5bf395602","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce trăsătură definește în mod specific ocluzia deschisă dentară sau falsă?","options":[{"id":"A","text":"Este cauzată de o displazie verticală primară."},{"id":"B","text":"Determină o mărire a etajului inferior al feței."},{"id":"C","text":"Prezintă o rotație de tip posterioar a mandibulei."},{"id":"D","text":"Se asociază frecvent cu o creștere excesivă a complexului dento-alveolar posterior."},{"id":"E","text":"Este localizată în general în zona anterioară și nu se extinde dincolo de canin."}],"correct":["E"],"pages":[513],"source":"set-2"},{"id":"set2-M45yI28Q","fingerprint":"72153f49cd81ced7","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Conform clasificării etiologice a lui Richardson, care dintre următoarele condiții pot determina ocluzie deschisă anterioară?","options":[{"id":"A","text":"O divergență a planurilor de ocluzie începând de la primul molar."},{"id":"B","text":"O displazie verticală primară."},{"id":"C","text":"Prezența unor afecțiuni reumatice la nivelul articulației temporo-mandibulare."},{"id":"D","text":"Creșterea incompletă a regiunii dento-alveolare la dinții permanenți în erupție."},{"id":"E","text":"Persistența interpunerii policelui după vârsta de 6 ani."}],"correct":["C","D","E"],"pages":[513],"source":"set-2"},{"id":"set2-BOcj8YME","fingerprint":"a7e0d1180015dd12","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care este o diferență fundamentală între ocluzia deschisă scheletică și cea dentară?","options":[{"id":"A","text":"Ocluzia deschisă dentară este denumită și ocluzie deschisă adevărată, iar cea scheletică este o pseudoocluzie deschisă."},{"id":"B","text":"Ocluzia deschisă dentară este limitată la zona anterioară, pe când cea scheletică poate avea o inocluzie verticală extinsă până la dinții posteriori."},{"id":"C","text":"Ocluzia deschisă scheletică se corectează spontan, în timp ce cea dentară necesită tratament complex."},{"id":"D","text":"Ocluzia deschisă scheletică este cauzată de obiceiuri vicioase, iar cea dentară de o predispoziție genetică."},{"id":"E","text":"În ocluzia deschisă dentară, ramul ascendent al mandibulei este scurt, iar în cea scheletică, acesta are dimensiuni normale."}],"correct":["B"],"pages":[513],"source":"set-2"},{"id":"set2-jElvh82t","fingerprint":"67b57c4dfebfc129","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele modificări ale mandibulei sunt asociate cu rahitismul în contextul etiologiei ocluziei deschise?","options":[{"id":"A","text":"Micșorarea etajului inferior al feței în partea sa anterioară."},{"id":"B","text":"Acțiunea mai puternică a mușchilor ridicători față de cei coborâtori."},{"id":"C","text":"Deformarea antegoniană a ramului orizontal."},{"id":"D","text":"Rotația anterioară a mandibulei."},{"id":"E","text":"Deschiderea unghiului mandibular."}],"correct":["C","E"],"pages":[514],"source":"set-2"},{"id":"set2-BVqVrI8D","fingerprint":"f25c34e9eeb6adc4","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care este mecanismul etiopatogenic prin care rahitismul contribuie la dezvoltarea ocluziei deschise?","options":[{"id":"A","text":"Dezvoltarea dento-alveolară compensează eficient decalajul creat între bazele osoase."},{"id":"B","text":"Dinții prezintă hiperplazii și hipercalcificări."},{"id":"C","text":"Se produce o rotație anterioară a maxilarului și o rotație posterioară a mandibulei."},{"id":"D","text":"Oasele maxilare devin mai puțin maleabile, rezistând forțelor musculare."},{"id":"E","text":"Tulburările de metabolism al calciului și fosforului se manifestă după primul an de viață."}],"correct":["C"],"pages":[514],"source":"set-2"},{"id":"set2-7XvIVThC","fingerprint":"aa14c554b5a02222","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații referitoare la factorii genetici în etiologia ocluziei deschise sunt adevărate?","options":[{"id":"A","text":"Mutațiile genei MMP9 sunt asociate cu ocluzia deschisă, iar această genă codifică sinteza matricei proteice."},{"id":"B","text":"Disostoza cleido-craniană este un sindrom genetic asociat cu ocluzia deschisă."},{"id":"C","text":"Tiparul facial de tip hiperdivergent determină un model scheletal vertical excesiv."},{"id":"D","text":"Pacienții cu tipar de creștere orizontal sunt mai predispuși la dezvoltarea ocluziei deschise."},{"id":"E","text":"Controlul genetic influențează dimensiunile sagitale și transversale, dar nu și pe cele verticale."}],"correct":["B","C"],"pages":[514],"source":"set-2"},{"id":"set2-8u_2cuTa","fingerprint":"e678dba45f25da26","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce caracterizează deglutiția de tip infantil și cum contribuie la apariția inocluziei verticale?","options":[{"id":"A","text":"Este cunoscută și sub denumirea de deglutiție „somatică”."},{"id":"B","text":"Se realizează cu arcadele dentare în contact și limba poziționată în interiorul acestora."},{"id":"C","text":"Stimulează dezvoltarea dento-alveolară verticală în zona frontală."},{"id":"D","text":"Inhibă procesul de căutare a antagonistului prin interpoziția limbii între arcade."},{"id":"E","text":"Este considerată o deglutiție anormală doar înainte de erupția dinților temporari."}],"correct":["D"],"pages":[514],"source":"set-2"},{"id":"set2-8_lVurQC","fingerprint":"fb20e20efb5c2623","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce sindrom genetic este menționat ca fiind asociat cu ocluzia deschisă?","options":[{"id":"A","text":"Sindromul Pierre Robin"},{"id":"B","text":"Sindromul Ehlers-Danlos"},{"id":"C","text":"Sindromul Marfan"},{"id":"D","text":"Sindromul Crouzon"},{"id":"E","text":"Sindromul Down"}],"correct":["E"],"pages":[514],"source":"set-2"},{"id":"set2-DPwv9q_P","fingerprint":"025898221092716f","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt afirmațiile corecte referitoare la persistența deglutiției de tip infantil după erupția dinților temporari?","options":[{"id":"A","text":"Este considerată o deglutiție anormală în această etapă de dezvoltare."},{"id":"B","text":"Este cunoscută și sub denumirea de deglutiție „somatică”."},{"id":"C","text":"Se caracterizează prin realizarea funcției cu arcadele dentare în contact."},{"id":"D","text":"Poate duce la inocluzie verticală prin inhibarea procesului de căutare a antagonistului."},{"id":"E","text":"Reprezintă un element cauzal frecvent întâlnit în etiologia ocluziei deschise."}],"correct":["A","D","E"],"pages":[514],"source":"set-2"},{"id":"set2-IqXnnn-y","fingerprint":"56e82e4b1f82fe99","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce efect principal are factorul dismetabolic legat de metabolismul calciului și fosforului în primul an de viață asupra structurii scheletice maxilare?","options":[{"id":"A","text":"Provoacă resorbția rădăcinilor dinților temporari, afectând indirect oasele."},{"id":"B","text":"Accelerează erupția dentară, fără a influența structura osoasă."},{"id":"C","text":"Nu are niciun impact asupra oaselor maxilare, afectând doar oasele lungi."},{"id":"D","text":"Crește densitatea osoasă a maxilarelor, prevenind deformările."},{"id":"E","text":"Determină o plasticitate osoasă crescută, făcând oasele vulnerabile la deformări."}],"correct":["E"],"pages":[514],"source":"set-2"},{"id":"set2-r7oGdh9g","fingerprint":"ba226926db7415a6","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele modificări sunt caracteristice mandibulei în contextul rahitismului, contribuind la etiologia ocluziei deschise?","options":[{"id":"A","text":"O rotație anterioară a mandibulei și o rotație posterioară a maxilarului."},{"id":"B","text":"Acțiunea mai puternică a mușchilor ridicători în raport cu cei coborâtori."},{"id":"C","text":"Deschiderea unghiului mandibular."},{"id":"D","text":"Deformarea antegoniană a ramului orizontal al mandibulei."},{"id":"E","text":"O rotație posterioară a mandibulei."}],"correct":["C","D","E"],"pages":[514],"source":"set-2"},{"id":"set2-2yQYM1iQ","fingerprint":"fa7b43f55bd8e0f2","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce tipar de creștere facială este asociat cu o predispoziție crescută pentru dezvoltarea ocluziei deschise, conform factorilor genetici?","options":[{"id":"A","text":"Tiparul de creștere vertical."},{"id":"B","text":"Tiparul de creștere orizontal."},{"id":"C","text":"Tiparul facial de tip hipodivergent."},{"id":"D","text":"Tiparul de creștere sagital."},{"id":"E","text":"Un tipar de creștere echilibrat, fără o dominantă specifică."}],"correct":["A"],"pages":[514],"source":"set-2"},{"id":"set2-icQ1BRpb","fingerprint":"a47f206f139a89ce","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele elemente genetice sunt menționate ca fiind asociate cu ocluzia deschisă?","options":[{"id":"A","text":"Mutații ale genei MMP9."},{"id":"B","text":"Mutații ale genei care codifică sinteza colagenului de tip I."},{"id":"C","text":"Sindromul Treacher-Collins."},{"id":"D","text":"Disostoza cleido-craniană."},{"id":"E","text":"Sindromul Down."}],"correct":["A","C","D","E"],"pages":[514],"source":"set-2"},{"id":"set2-r4EkXcnd","fingerprint":"9186c5214b0eb0a8","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce rol joacă metaloproteinazele matriceale, a căror sinteză este codificată de gena MMP9, în contextul dezvoltării osoase?","options":[{"id":"A","text":"Sunt implicate în procesele de modelare și remodelare osoasă."},{"id":"B","text":"Sunt responsabile exclusiv de calcificarea matricei proteice osoase."},{"id":"C","text":"Asigură sinteza fibrelor de colagen din matricea osoasă."},{"id":"D","text":"Au un rol principal în metabolismul calciului și fosforului la nivel celular."},{"id":"E","text":"Inhibă procesul de creștere osoasă în perioada copilăriei."}],"correct":["A"],"pages":[514],"source":"set-2"},{"id":"set2-Oxa3Y9Ew","fingerprint":"f15f2c23be2b6c49","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect deglutiția de tip infantil și consecințele persistenței sale după erupția dinților temporari?","options":[{"id":"A","text":"Persistența sa poate duce la inocluazie verticală din cauza interpoziției limbii între arcade."},{"id":"B","text":"Se caracterizează prin realizarea deglutiției cu arcadele dentare în contact permanent."},{"id":"C","text":"Este cunoscută și sub denumirea de deglutiție „somatică”."},{"id":"D","text":"Urmare a interpoziției limbii, este inhibat procesul de căutare a dintelui antagonist."},{"id":"E","text":"Anumiți autori consideră că aceasta ar putea fi o consecință a ocluziei deschise, reprezentând o lipsă de adaptare a limbii."}],"correct":["A","D","E"],"pages":[515],"source":"set-2"},{"id":"set2-7yHhnTXC","fingerprint":"ae0e843dd6919bf5","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce modificări specifice au fost observate la pacienții cu tulburări respiratorii care dezvoltă ocluzie deschisă?","options":[{"id":"A","text":"Hipertrofia amigdalelor palatine și o poziție normală a mandibulei."},{"id":"B","text":"Rotația mandibulei în sens invers acelor de ceasornic."},{"id":"C","text":"Rotația mandibulei în sensul acelor de ceasornic și un etaj inferior mărit."},{"id":"D","text":"O poziționare superioară a limbii datorită efortului respirator."},{"id":"E","text":"Un etaj inferior al feței micșorat."}],"correct":["C"],"pages":[515],"source":"set-2"},{"id":"set2-gzsznW8U","fingerprint":"425c5ea1796607b4","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la deficiența neuromusculară ca factor etiologic al ocluziei deschise, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Ocluzia deschisă este considerată de unii autori o consecință a creșterii tonusului muscular masticator."},{"id":"B","text":"Ocluzia deschisă este întotdeauna cauza și niciodată efectul activității musculare scăzute."},{"id":"C","text":"Lipsa ghidajului anterior, specifică ocluziei deschise, determină un ciclu masticator mai lung și cu amplitudine mai mare."},{"id":"D","text":"La pacienții cu distrofii musculare, mușchii masticatori hipotoni pot permite suprapoziția zonelor posterioare."},{"id":"E","text":"Modificarea tiparului dinamic al masticației poate conduce la o activitate musculară mai redusă la pacienții cu ocluzie deschisă."}],"correct":["D","E"],"pages":[515],"source":"set-2"},{"id":"set2-PP5jykWz","fingerprint":"5d7adddd3029facb","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele efecte sunt asociate cu interpozițiile heterotrope combinate cu fenomenul de succiune?","options":[{"id":"A","text":"Echilibrarea forțelor exercitate de limbă, buze și obraji."},{"id":"B","text":"Denivelări ale planului de ocluzie."},{"id":"C","text":"Extruzia dinților în zona afectată."},{"id":"D","text":"Deformarea arcadelor alveolo-dentare."},{"id":"E","text":"Inocluzie verticală."}],"correct":["B","D","E"],"pages":[515],"source":"set-2"},{"id":"set2-rjov44Z8","fingerprint":"2c3a997a47ec0227","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care factor local este considerat de majoritatea specialiștilor drept principala cauză a ocluziei deschise parțiale?","options":[{"id":"A","text":"Tulburările fonatorii."},{"id":"B","text":"Obstrucția căilor respiratorii superioare."},{"id":"C","text":"Deficiența neuromusculară și hipotonia mușchilor masticatori."},{"id":"D","text":"Persistența deglutiției de tip infantil."},{"id":"E","text":"Interpozițiile, fie ele heterotrope sau autotrope."}],"correct":["E"],"pages":[515],"source":"set-2"},{"id":"set2-5-buT_Kr","fingerprint":"879b5dcd5d07e80d","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele reprezintă interpoziții heterotrope ce pot fi incriminate în producerea ocluziei deschise parțiale?","options":[{"id":"A","text":"Interpunerea obrajilor între arcadele dentare."},{"id":"B","text":"Interpunerea limbii între arcadele dentare."},{"id":"C","text":"Obiceiul de interpoziție a degetului/degetelor."},{"id":"D","text":"Utilizarea suzetei."},{"id":"E","text":"Interpunerea unor obiecte precum creioanele."}],"correct":["C","D","E"],"pages":[516],"source":"set-2"},{"id":"set2-fVSItMrH","fingerprint":"062b3899e208d6f1","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următorii factori influențează severitatea malocluziei de tip ocluzie deschisă cauzată de obiceiul vicios de succiune a degetului?","options":[{"id":"A","text":"Vârsta pacientului la care persistă obiceiul."},{"id":"B","text":"Prezența concomitentă a interpoziției limbii."},{"id":"C","text":"Durata obiceiului vicios."},{"id":"D","text":"Tipul degetului interpus (police sau index)."},{"id":"E","text":"Frecvența cu care se practică obiceiul."}],"correct":["A","C","E"],"pages":[516],"source":"set-2"},{"id":"set2-mZm5eGe9","fingerprint":"11fc1a33da07062b","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce consecință specifică poate avea interpoziția obrajilor, uni sau bilateral, între arcadele dentare?","options":[{"id":"A","text":"Vestibularizarea dinților laterali."},{"id":"B","text":"Limitarea sau oprirea dezvoltării verticale a arcadelor alveolo-dentare în zonele laterale."},{"id":"C","text":"Intruzia dinților anteriori."},{"id":"D","text":"Deformarea asimetrică a arcadelor alveolo-dentare."},{"id":"E","text":"Inocluzie verticală în regiunea frontală."}],"correct":["B"],"pages":[516],"source":"set-2"},{"id":"set2-QbCHHqcw","fingerprint":"0705d9097d199c0d","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce efecte are poziționarea anterioară și joasă a limbii asupra dezvoltării maxilarelor?","options":[{"id":"A","text":"Favorizează dezvoltarea mandibulei și influențează negativ dezvoltarea maxilarului superior."},{"id":"B","text":"Inhibă dezvoltarea ambelor maxilare, conducând la micrognație generalizată."},{"id":"C","text":"Determină o dezvoltare verticală excesivă a maxilarului superior."},{"id":"D","text":"Stimulează dezvoltarea maxilarului superior prin presiune constantă asupra bolții palatine."},{"id":"E","text":"Nu are nicio influență asupra dezvoltării oaselor maxilare, afectând doar poziția dinților."}],"correct":["A"],"pages":[516],"source":"set-2"},{"id":"set2-G31VJ73I","fingerprint":"ccde5102399c956d","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care este efectul principal al macroglosiei asupra poziției dinților?","options":[{"id":"A","text":"Erupția incompletă a dinților laterali."},{"id":"B","text":"Anchiloza dentară în dentiția permanentă."},{"id":"C","text":"Infrapoziția dinților anteriori."},{"id":"D","text":"Retruzia accentuată a incisivilor."},{"id":"E","text":"Vestibularizarea dinților."}],"correct":["E"],"pages":[516],"source":"set-2"},{"id":"set2-hw7KcXYt","fingerprint":"ce28402400bfaffd","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce mecanism specific poate duce la instalarea ocluziei deschise în dentiția permanentă ca urmare a unor forțe traumatice exercitate asupra dentiției temporare?","options":[{"id":"A","text":"Degenerarea condiliană bilaterală."},{"id":"B","text":"Inducerea anchilozei dentare la dinții temporari, urmată de erupția incompletă a dinților permanenți."},{"id":"C","text":"Determinarea de contacte premature la nivelul dinților posteriori."},{"id":"D","text":"Formarea de bride cicatriciale labio-geniene."},{"id":"E","text":"Alterarea procesului de creștere verticală a maxilarului superior."}],"correct":["B"],"pages":[516],"source":"set-2"},{"id":"set2-AejryhRO","fingerprint":"08ea182353047231","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afecțiuni care interesează articulația temporo-mandibulară pot fi o cauză a apariției ocluziei deschise prin inducerea degenerării condiliene?","options":[{"id":"A","text":"Cicatricile cheloide labio-mentoniere."},{"id":"B","text":"Spondilita anchilozantă."},{"id":"C","text":"Boala reumatoidă autoimună."},{"id":"D","text":"Sclerodermia."},{"id":"E","text":"Osteomielita regiunii frontale a maxilarului superior."}],"correct":["B","C","D"],"pages":[516],"source":"set-2"},{"id":"set2-SH6yZkbP","fingerprint":"059ce223808effd9","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"În ce context erupția molarilor de minte poate produce ocluzie deschisă?","options":[{"id":"A","text":"Exclusiv în prezența unor obiceiuri vicioase de succiune."},{"id":"B","text":"În situația unei ocluzii cap la cap în zona frontală sau cu o supraacoperire mică."},{"id":"C","text":"Atunci când este asociată cu macroglosie."},{"id":"D","text":"Doar dacă erupția acestora este asimetrică."},{"id":"E","text":"În cazul pacienților cu resorbție condiliană idiopatică."}],"correct":["B"],"pages":[516],"source":"set-2"},{"id":"set2-GsHYnOkl","fingerprint":"2a54406b771910a1","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care sunt caracteristicile resorbției idiopatice a condilului mandibular?","options":[{"id":"A","text":"Este întotdeauna asociată cu sindromul Sjögren."},{"id":"B","text":"Este o complicație a tratamentelor ortodontice cu forțe de intensitate mare."},{"id":"C","text":"Apare la persoanele în vârstă și este de obicei unilaterală."},{"id":"D","text":"Se regăsește la adolescenți, mai ales la sexul feminin, și afectează bilateral condilii."},{"id":"E","text":"Este cauzată de traumatisme la nivelul condilului în perioada de creștere."}],"correct":["D"],"pages":[516],"source":"set-2"},{"id":"set2-7cZmhJJM","fingerprint":"09d22856dd05f96f","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele situații sunt considerate factori ce pot determina apariția unei ocluzii deschise?","options":[{"id":"A","text":"Reincluzia molarilor temporari sau, în mod excepțional, a molarului de 6 ani."},{"id":"B","text":"Reinserția molarilor temporari după o avulsie traumatică."},{"id":"C","text":"Forțele ortodontice de intensitate redusă, aplicate pe o perioadă lungă de timp."},{"id":"D","text":"Utilizarea forțelor ortodontice de intensitate mare în stadiile incipiente ale tratamentului cu aparate fixe."},{"id":"E","text":"Necesități terapeutice temporare în cadrul unui tratament ortodontic."}],"correct":["A","D","E"],"pages":[517],"source":"set-2"},{"id":"set2-9z4WiHwV","fingerprint":"b8904b8b307f33cf","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt semnele clinice faciale caracteristice ocluziei deschise totale?","options":[{"id":"A","text":"Fanta labială deschisă, prin care incisivii superiori sunt vizibili în repaus."},{"id":"B","text":"Șanțul labio-mentonier accentuat și profund."},{"id":"C","text":"Creșterea înălțimii etajului inferior, care poate depăși etajul superior cu peste 1 cm."},{"id":"D","text":"Profilul facial accentuat concav."},{"id":"E","text":"Unghiul mandibular mărit, depășind valoarea normală de 120º - 125º."}],"correct":["C","E"],"pages":[517],"source":"set-2"},{"id":"set2-MOdRZJnT","fingerprint":"4dbad72434cdb1bc","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la modificările intraorale din ocluzia deschisă, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Modificările de volum dentar se pot manifesta prin coroane de volum redus, de exemplu, incisivii centrali superiori având dimensiunea incisivilor laterali superiori."},{"id":"B","text":"Modificările de structură, volum și formă ale dinților sunt caracteristice și prezente constant atât în ocluzia deschisă totală, cât și în cea parțială."},{"id":"C","text":"Modificările de formă pot include inversarea raportului de mărime între dinți, cum ar fi molarii de 12 ani mai mari decât molarii de 6 ani."},{"id":"D","text":"Coordonata verticală a spațiului de inocluzie are valoare prognostică, o valoare mai mare indicând o corectare terapeutică mai facilă."},{"id":"E","text":"Coordonata verticală a inocluziei se referă la numărul de dinți afectați."}],"correct":["A","C"],"pages":[517],"source":"set-2"},{"id":"set2-tKv3m2BH","fingerprint":"79f3aad0136b3f5e","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele descrieri corespunde semnelor clinice faciale întâlnite în ocluzia deschisă parțială?","options":[{"id":"A","text":"Fanta labială este închisă, iar incisivii superiori sunt vizibili în repaus."},{"id":"B","text":"Înălțimea etajului inferior este constant semnificativ mărită."},{"id":"C","text":"Procheilia superioară este un semn clinic absent în această formă."},{"id":"D","text":"Profilul este întotdeauna accentuat convex."},{"id":"E","text":"Unghiul mandibular are valori normale sau este doar puțin mărit."}],"correct":["E"],"pages":[517],"source":"set-2"},{"id":"set2-YUgbwNaT","fingerprint":"b313b2272175e8e1","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce modificări specifice la nivelul mandibulei sunt asociate cu ocluzia deschisă totală?","options":[{"id":"A","text":"Prezența unei ancoșe largi și adânci, orientată în jos, în regiunea antegonionului."},{"id":"B","text":"Oblicitatea ramului orizontal al mandibulei este redusă."},{"id":"C","text":"Unghiul mandibular este micșorat, având valori sub 120º."},{"id":"D","text":"Mentonul este proeminent și ridicat."},{"id":"E","text":"Ramul ascendent al mandibulei este scurtat."}],"correct":["A","E"],"pages":[517],"source":"set-2"},{"id":"set2-cl5c8-aR","fingerprint":"803eeb2aff33c5d6","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"În ceea ce privește diagnosticul inocluziei verticale, ce reprezintă coordonatele sale?","options":[{"id":"A","text":"Coordonata orizontală materializează înălțimea spațiului de inocluzie și are valoare prognostică."},{"id":"B","text":"Un exemplu de definire a coordonatei orizontale este \"inocluzie verticală de la canin la canin\"."},{"id":"C","text":"Coordonata verticală se delimitează între dinții care sunt în contact cu antagoniștii."},{"id":"D","text":"Coordonata verticală cuantifică gradul de convexitate al profilului facial."},{"id":"E","text":"Coordonata orizontală se referă la numărul de dinți interesați de modificarea de ocluzie."}],"correct":["B","E"],"pages":[517],"source":"set-2"},{"id":"set2-oSN2t4PP","fingerprint":"27b98c1e32d3d9ad","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care sunt caracteristicile definitorii ale celor două coordonate ale inocluziei verticale în ocluzia deschisă?","options":[{"id":"A","text":"Coordonata verticală se referă la numărul de dinți afectați de modificarea de ocluzie."},{"id":"B","text":"O valoare mică a coordonatei verticale indică o corectare terapeutică mai dificilă."},{"id":"C","text":"Ambele coordonate se măsoară întotdeauna în regiunea anterioară a arcadelor dentare."},{"id":"D","text":"Coordonata orizontală materializează înălțimea spațiului de inocluzie și are valoare prognostică."},{"id":"E","text":"Coordonata orizontală se delimitează între dinții care sunt în contact cu antagoniștii."}],"correct":["E"],"pages":[518],"source":"set-2"},{"id":"set2-jZyoR47T","fingerprint":"d825814e9f269566","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice ocluziei deschise parțiale?","options":[{"id":"A","text":"Cuprinde un număr mai redus de dinți."},{"id":"B","text":"Poate fi asimetrică."},{"id":"C","text":"Spațiul de inocluzie verticală cuprinde un număr mare de dinți, frecvent simetric."},{"id":"D","text":"Prezintă o localizare predominant anterioară."},{"id":"E","text":"Înălțimea spațiului de inocluzie verticală depășește frecvent 1 cm."}],"correct":["A","B","D"],"pages":[518],"source":"set-2"},{"id":"set2-74ypX6fE","fingerprint":"14763f651ffcad63","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce modificări la nivelul arcadelor dentare se întâlnesc în mod constant în ocluzia deschisă?","options":[{"id":"A","text":"La arcada inferioară, incisivii sunt adesea dispuși în linie dreaptă, conturând o formă de trapez."},{"id":"B","text":"La arcada superioară, planul de ocluzie descrie în regiunea anterioară o curbă cu convexitatea către planul de ocluzie."},{"id":"C","text":"Modificările sunt mai evidente la arcada inferioară decât la cea superioară."},{"id":"D","text":"Osul alveolar nu prezintă modificări de contur, acestea fiind limitate strict la nivel dentar."},{"id":"E","text":"La nivelul dinților anteriori se constată supradenție."}],"correct":["A"],"pages":[518],"source":"set-2"},{"id":"set2-Mx2Xq6l5","fingerprint":"79e41bb6938572fe","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele semne clinice intraorale sunt considerate patognomonice pentru etiologia dismetabolică a ocluziei deschise?","options":[{"id":"A","text":"Îngustarea arcadei superioare asociată cu înclinarea anterioară a osului alveolar."},{"id":"B","text":"Bolta palatină îngustată și adâncă."},{"id":"C","text":"Infradenția anterioară și denivelarea planului de ocluzie."},{"id":"D","text":"Orientarea incisivilor inferiori în linie dreaptă."},{"id":"E","text":"Displaziile de smalț."}],"correct":["D","E"],"pages":[518],"source":"set-2"},{"id":"set2-oKNeu2m9","fingerprint":"e2de4a478e88fe2b","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce semne radiologice sunt sugestive pentru ocluzia deschisă gravă?","options":[{"id":"A","text":"Suprapoziția incisivilor și infrapoziția molarilor."},{"id":"B","text":"Raportul dintre înălțimea posterioară și înălțimea anterioară facială mai mare de 0,65."},{"id":"C","text":"Creșterea înălțimii verticale a ramului ascendent mandibular."},{"id":"D","text":"Rotația posterioară a mandibulei."},{"id":"E","text":"O oblicitate redusă a ramului orizontal al mandibulei."}],"correct":["D"],"pages":[518],"source":"set-2"},{"id":"set2-goNe0-wR","fingerprint":"3afa079faf0aac9f","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele afirmații referitoare la parametrii cefalometrici în ocluzia deschisă este corectă?","options":[{"id":"A","text":"Unghiul Tweed este mult scăzut față de valoarea sa normală de 22°-25°."},{"id":"B","text":"Unghiul condilian este de asemenea mărit, depășind valoarea de 137°."},{"id":"C","text":"Toate unghiurile ce au ca latură planul bazal mandibular sunt scăzute."},{"id":"D","text":"Unghiul B a lui Schwarz, conturat între planul bazal mandibular și planul Frankfurt, este crescut."},{"id":"E","text":"Unghiul mandibular este mărit, având valori sub cele normale de 120-135°."}],"correct":["B"],"pages":[518],"source":"set-2"},{"id":"set2-HvXBDttC","fingerprint":"d57fde8b5e858f4a","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce informații corecte referitoare la unghiul Tweed și unghiul B a lui Schwarz se pot desprinde din analiza cefalometrică a unei ocluzii deschise?","options":[{"id":"A","text":"Unghiul B a lui Schwarz este crescut, mai ales în ocluzia deschisă prin interpoziție."},{"id":"B","text":"Unghiul B a lui Schwarz are o valoare normală de 22°-25°."},{"id":"C","text":"Unghiul Tweed este delimitat între baza mandibulei și planul Frankfurt și este crescut în ocluzia deschisă."},{"id":"D","text":"Unghiul Tweed are valoare prognostică, o valoare mai crescută indicând un prognostic terapeutic favorabil."},{"id":"E","text":"Unghiul B a lui Schwarz este de obicei scăzut, în special în ocluzia deschisă dismetabolică."}],"correct":["C"],"pages":[518],"source":"set-2"},{"id":"set2-kTqkCx1_","fingerprint":"cacc6d2c60b9e04f","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele tulburări funcționale sunt considerate consecințe ale ocluziei deschise?","options":[{"id":"A","text":"Tulburări la nivelul articulației temporo-mandibulare, care apar constant, indiferent de extinderea spațiului de inocluzie."},{"id":"B","text":"Tulburări ale funcției masticatorii, cauzate de reducerea numărului de contacte dentare."},{"id":"C","text":"Tulburări ale funcției fonetice, determinate de interpoziția limbii între arcade la pronunțarea fonemelor dentale."},{"id":"D","text":"Tulburări ale funcției respiratorii, precum respirația orală, asociate cu o arcadă superioară îngustată."},{"id":"E","text":"Tulburări ale funcției fizionomice, accentuate în forma totală și constituind un factor de stres psihic."}],"correct":["B","C","D","E"],"pages":[519],"source":"set-2"},{"id":"set2-qoTPO_Je","fingerprint":"3187899211d192d4","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Ce elemente pot fi considerate atât cauze, cât și efecte sau mecanisme de adaptare în contextul ocluziei deschise?","options":[{"id":"A","text":"Suprasolicitarea dinților în contact și hipofuncția celor în infrapoziție."},{"id":"B","text":"Reducerea eficienței masticatorii și imposibilitatea inciziei alimentelor."},{"id":"C","text":"Bolta palatină adâncă și fanta labială deschisă."},{"id":"D","text":"Afectarea parodonțiului și incontinența salivară."},{"id":"E","text":"Interpoziția limbii și respirația orală."}],"correct":["E"],"pages":[519],"source":"set-2"},{"id":"set2-Z0p1NLXG","fingerprint":"7776ec48fee03da3","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Pe lângă tulburările funcționale ale aparatului dento-maxilar, ce alte implicații poate avea ocluzia deschisă?","options":[{"id":"A","text":"Suprasolicitarea funcțională a dinților aflați în contact interarcadic."},{"id":"B","text":"Afectarea parodonțiului dinților în infraocluzie din cauza hipofuncției și alterării autocurățirii."},{"id":"C","text":"O solicitare funcțională echilibrată a tuturor dinților de pe arcadă."},{"id":"D","text":"Incontinența salivară, cu pierderi de salivă mai ales în timpul funcției fonatorii."},{"id":"E","text":"Îmbunătățirea procesului de autocurățire la nivelul dinților nefuncționali."}],"correct":["A","B","D"],"pages":[519],"source":"set-2"},{"id":"set2-pusa9qxy","fingerprint":"f1e11c19e4284d57","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele situații clinice trebuie luate în considerare în diagnosticul diferențial al ocluziei deschise?","options":[{"id":"A","text":"Informațiile anamnestice privind antecedentele heredo-colaterale."},{"id":"B","text":"Semnele clinice și radiologice caracteristice anomaliei."},{"id":"C","text":"Tulburările funcționale care se intercondiționează și se influențează reciproc."},{"id":"D","text":"Spațiul de inocluzie verticală cu caracter tranzitoriu din perioada erupției dentare."},{"id":"E","text":"Spațiul de inocluzie verticală permanent, creat ca necesitate terapeutică."}],"correct":["D"],"pages":[519],"source":"set-2"},{"id":"set2-7vlZW0It","fingerprint":"13ba8eced11d69f6","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"În ce mod este afectată funcția masticatorie în cazul unui pacient cu ocluzie deschisă?","options":[{"id":"A","text":"Incizia alimentelor devine imposibilă, dar triturarea acestora rămâne neafectată."},{"id":"B","text":"Interpoziția limbii în timpul masticației facilitează formarea bolului alimentar."},{"id":"C","text":"Crește eficiența triturării alimentelor datorită spațiului vertical liber."},{"id":"D","text":"Se reduce considerabil eficiența masticatorie prin micșorarea numărului de unități dentare în contact."},{"id":"E","text":"Toți dinții sunt supuși unor forțe masticatorii reduse pentru a compensa anomalia."}],"correct":["D"],"pages":[519],"source":"set-2"},{"id":"set2-HgQyuq5B","fingerprint":"1c3ff62fc23af114","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt factorii care influențează prognosticul în cazul unei ocluzii deschise?","options":[{"id":"A","text":"Asocierea cu compresiunea de maxilar, care este considerată un factor agravant."},{"id":"B","text":"Asocierea cu prognatismul mandibular adevărat, considerat un factor favorabil."},{"id":"C","text":"Momentul instituirii tratamentului ortodontic."},{"id":"D","text":"Factorii cauzali implicați în apariția anomaliei."},{"id":"E","text":"Vârsta la care a fost depistată anomalia."}],"correct":["C","D","E"],"pages":[520],"source":"set-2"},{"id":"set2-25NW_pYa","fingerprint":"ddbdc96e6ae1b4c4","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt obiectivele terapeutice principale ale tratamentului ocluziei deschise?","options":[{"id":"A","text":"Echilibrarea relațiilor de ocluzie, cu precădere în plan sagital."},{"id":"B","text":"Corectarea exclusiv chirurgicală a discrepanțelor scheletale."},{"id":"C","text":"Armonizarea dezvoltării arcadelor alveolo-dentare."},{"id":"D","text":"Normalizarea funcțiilor aparatului dento-maxilar."},{"id":"E","text":"Echilibrarea relațiilor de ocluzie, cu precădere în plan vertical."}],"correct":["C","D","E"],"pages":[520],"source":"set-2"},{"id":"set2-eUmYbjOF","fingerprint":"dab59840619920bc","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce măsuri specifice sunt incluse în tratamentul profilactico-preventiv al ocluziei deschise?","options":[{"id":"A","text":"Profilaxia și/sau tratamentul tulburărilor metabolice, cum ar fi rahitismul."},{"id":"B","text":"Aplicarea de aparate ortodontice fixe pentru a ghida erupția dentară."},{"id":"C","text":"Instituirea unui comportament alimentar sanogen, începând imediat după naștere."},{"id":"D","text":"Amânarea oricărei intervenții până la finalizarea creșterii și dezvoltării."},{"id":"E","text":"Depistarea și decondiționarea obiceiurilor vicioase înainte ca acestea să producă efecte majore."}],"correct":["A","C","E"],"pages":[520],"source":"set-2"},{"id":"set2-YDCHMbM4","fingerprint":"e756820bf3ecc88c","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la managementul disfuncțiilor asociate cu ocluzia deschisă, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Reeducarea funcției de deglutiție trebuie realizată înaintea decondiționării obiceiurilor vicioase de interpoziție."},{"id":"B","text":"În cazul respirației orale, gimnastica respiratorie se impune imediat după eliberarea chirurgicală a pasajului aerian."},{"id":"C","text":"În cazul respirației orale, abordarea terapeutică este exclusiv ortodontică, fără a necesita o evaluare ORL."},{"id":"D","text":"Terapia prin exerciții pentru deglutiție poate fi combinată cu aparate ortodontice prevăzute cu elemente precum scutul lingual."},{"id":"E","text":"Scopul principal al reeducării deglutiției este exclusiv însușirea unei poziții corecte a limbii în repaus."}],"correct":["B","D"],"pages":[520],"source":"set-2"},{"id":"set2-vT4xmboW","fingerprint":"118722d8c58dc226","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care este afirmația corectă cu privire la obiceiurile vicioase în contextul profilaxiei ocluziei deschise?","options":[{"id":"A","text":"Decondiționarea obiceiurilor vicioase este o componentă a tratamentului curativ, nu a celui profilactic."},{"id":"B","text":"Tratamentul profilactic vizează decondiționarea lor după ce au produs efecte majore, pentru a preveni agravarea."},{"id":"C","text":"Acestea nu pot produce modificări ireversibile la nivelul structurilor dento-maxilare indiferent de vârstă."},{"id":"D","text":"Se consideră că până la vârsta de 5-6 ani, aceste obiceiuri nu pot produce modificări ireversibile."},{"id":"E","text":"Reeducarea deglutiției trebuie începută întotdeauna înaintea decondiționării obiceiurilor vicioase de interpoziție."}],"correct":["D"],"pages":[520],"source":"set-2"},{"id":"set2-G-ZZsMo4","fingerprint":"b4cbebccf1a88a59","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Cum influențează etiologia ocluziei deschise receptivitatea la tratament?","options":[{"id":"A","text":"Etiologia nu are nicio influență asupra receptivității la tratament, prognosticul fiind identic."},{"id":"B","text":"Etiologia plurifactorială simplifică abordarea terapeutică datorită multiplelor opțiuni de tratament."},{"id":"C","text":"Ocluziile deschise determinate în principal de factorii locali sunt mai receptive la tratament."},{"id":"D","text":"Cazurile cu determinare genetică sunt mai receptive la tratament decât cele determinate de factori locali."},{"id":"E","text":"Toate formele de ocluzie deschisă, indiferent de etiologie, răspund cel mai bine la tratamentul ortodontico-chirurgical."}],"correct":["C"],"pages":[520],"source":"set-2"},{"id":"set2-he6A6Mrg","fingerprint":"fa28c04aee5213d4","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt caracteristicile tratamentului ortodontic interceptiv?","options":[{"id":"A","text":"Prin eliminarea factorilor cauzali, poate face inutilă o intervenție ortodontică ulterioară."},{"id":"B","text":"Presupune întotdeauna utilizarea de aparate fixe poliagregate complexe."},{"id":"C","text":"Este o etapă care se aplică exclusiv după finalizarea tratamentului curativ."},{"id":"D","text":"În cazul formelor grave, poate scurta durata tratamentului ortodontic activ."},{"id":"E","text":"Acesta urmărește limitarea sau stoparea modificărilor și consecințelor unei anomalii."}],"correct":["A","D","E"],"pages":[521],"source":"set-2"},{"id":"set2-tokR_NgX","fingerprint":"726143afd41800a8","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"De ce este important ca tratamentul curativ al anomaliilor dento-maxilare să fie aplicat cât mai precoce?","options":[{"id":"A","text":"Pentru că permite finalizarea tratamentului fără a necesita o perioadă de contenție."},{"id":"B","text":"Fiindcă răspunsul terapeutic este mai slab înainte de finalizarea creșterii."},{"id":"C","text":"Deoarece potențialul de recidivă scade semnificativ după vârsta de 20 de ani."},{"id":"D","text":"Deoarece anomalia are o dinamică evolutivă agravantă în timp."},{"id":"E","text":"Pentru că tabloul clinic este mai grav la vârste mici."}],"correct":["D"],"pages":[521],"source":"set-2"},{"id":"set2-NCaMiyYp","fingerprint":"cfd3bb5247cf8f07","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt obiectivele tratamentului curativ în cazul ocluziei deschise?","options":[{"id":"A","text":"Corectarea decalajului existent între oasele maxilare."},{"id":"B","text":"Permiterea egresiunii dinților localizați în zona de inocluzie verticală."},{"id":"C","text":"Ingresiunea dinților care nu se află în zona de inocluzie verticală."},{"id":"D","text":"Înlăturarea consecințelor anomaliei asupra aparatului dento-maxilar."},{"id":"E","text":"Prevenirea egresiunii oricărui grup dentar pentru a stabiliza ocluzia."}],"correct":["A","B","C","D"],"pages":[521],"source":"set-2"},{"id":"set2-QQEyTDg5","fingerprint":"9f13221fdb9b2545","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce presupune tratamentul ortodontic tardiv, inițiat după finalizarea proceselor de creștere?","options":[{"id":"A","text":"Necesitatea frecventă a unor intervenții interdisciplinare, inclusiv chirurgicale."},{"id":"B","text":"Simplitate terapeutică sporită, deoarece procesele de creștere nu mai interferează cu tratamentul."},{"id":"C","text":"O durată redusă a contenției datorită stabilității osoase la adult."},{"id":"D","text":"O durată mai mare atât a tratamentului ortodontic activ, cât și a perioadei de contenție."},{"id":"E","text":"O probabilitate redusă ca anomalia să fie tratată exclusiv prin mijloace ortodontice."}],"correct":["A","D","E"],"pages":[521],"source":"set-2"},{"id":"set2-m0qt7s_d","fingerprint":"c68c43fa317e8e0b","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații despre contenție și recidivă în tratamentul ocluziei deschise sunt corecte?","options":[{"id":"A","text":"Ocluzia deschisă este o anomalie cu un potențial mare de recidivă."},{"id":"B","text":"Datorită dificultății tratamentului, perioada de contenție poate fi mai scurtă decât cea activă."},{"id":"C","text":"Monitorizarea post-tratament prin controale periodice nu este obligatorie."},{"id":"D","text":"Prezența molarilor de minte poate spori riscul de recidivă."},{"id":"E","text":"Durata perioadei de contenție trebuie să fie cel puțin egală cu cea a tratamentului activ."}],"correct":["A","D","E"],"pages":[521],"source":"set-2"},{"id":"set2-5TC_vgC8","fingerprint":"362a51ca2295b905","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce elemente sunt considerate esențiale pentru reușita terapeutică în tratamentul ocluziei deschise?","options":[{"id":"A","text":"Înțelegerea factorilor cauzali, a modului în care interrelaționează și identificarea cauzei principale."},{"id":"B","text":"Stabilirea unui diagnostic corect, bazat pe simptomatologia specifică."},{"id":"C","text":"Obținerea unui rezultat stabil în timp, pe lângă cel estetic și funcțional."},{"id":"D","text":"O abordare terapeutică individualizată pentru fiecare caz."},{"id":"E","text":"Aplicarea unui protocol de tratament standardizat pentru toți pacienții, pentru a asigura consecvența."}],"correct":["A","B","C","D"],"pages":[521],"source":"set-2"},{"id":"set2-p_-F_94v","fingerprint":"c6442497d8117502","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt asocierile corecte referitoare la clasificarea și terminologia ocluziei deschise?","options":[{"id":"A","text":"În clasificarea lui Angle, ocluzia deschisă totală este o entitate conturată exclusiv în clasa a III-a."},{"id":"B","text":"În clasificarea lui Angle, ocluzia deschisă parțială se încadrează de regulă în clasa I."},{"id":"C","text":"În clasificarea clinico-antropologică, anomalia este încadrată în grupa dizarmoniilor dento-alveolare cu modificări în plan vertical."},{"id":"D","text":"Ocluzia deschisă a fost descrisă pentru prima dată de Carabelli ca o entitate distinctă a malocluziilor."},{"id":"E","text":"În clasificarea școlii germane, anomalia este denumită „mordex apertus”."}],"correct":["B","C","D"],"pages":[512],"source":"set-2"},{"id":"set2-_aWGhX9U","fingerprint":"c0c93bc33222f5cc","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt caracteristicile clinice și cefalometrice asociate ocluziei deschise scheletice adevărate?","options":[{"id":"A","text":"Micșorarea înălțimii faciale anterioare concomitent cu creșterea înălțimii faciale posterioare."},{"id":"B","text":"Rotația de tip anterior a mandibulei pe parcursul dezvoltării scheletale."},{"id":"C","text":"Divergența planurilor de ocluzie începând de la nivelul primului molar."},{"id":"D","text":"Prezența unui ram ascendent mandibular scurt și a unui unghi mandibular cu valori crescute."},{"id":"E","text":"Mărirea etajului inferior al feței și incompetența labială."}],"correct":["C","D","E"],"pages":[512],"source":"set-2"},{"id":"set2-i2TDCSoR","fingerprint":"14c4ebf4b341c633","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele afirmații referitoare la epidemiologia și incidența ocluziei deschise este validă?","options":[{"id":"A","text":"Anomalia prezintă o tendință de autocorectare pe parcursul perioadei dentiției mixte."},{"id":"B","text":"Frecvența anomaliei crește odată cu înaintarea în vârstă a copilului."},{"id":"C","text":"Rezultatele studiilor epidemiologice indică o afectare predominantă a sexului feminin."},{"id":"D","text":"Frecvența ocluziei deschise la nivel național atinge un procent constant de 10-15%."},{"id":"E","text":"Ocluzia deschisă posterioară reprezintă forma clinică cel mai frecvent întâlnită la copii."}],"correct":["A"],"pages":[512],"source":"set-2"},{"id":"set2-wYgGJtsz","fingerprint":"2bb18163de4e6af8","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la clasificarea ocluziei deschise în funcție de severitate, etiologie și planurile de referință, care dintre afirmații descriu corect entitățile clinice?","options":[{"id":"A","text":"Ocluzia deschisă complexă este o entitate limitată exclusiv la dinți și la procesul alveolar."},{"id":"B","text":"Pseudoocluzia deschisă asociază modificări dentare vizibile cefalometric, cum ar fi infrapoziția și vestibulo-înclinarea dinților anteriori."},{"id":"C","text":"Ocluzia deschisă dentară implică alterarea severă a bazelor osoase maxilare și mandibulare."},{"id":"D","text":"Ocluzia deschisă parțială are o severitate redusă, având drept cauză principală factori locali precum interpozițiile."},{"id":"E","text":"Ocluzia deschisă totală este o formă severă în care mecanismul etiologic este dominat de factori generali, dismetabolici sau genetici."}],"correct":["B","D","E"],"pages":[512],"source":"set-2"},{"id":"set2-kjLh4KJT","fingerprint":"36c7207425116dd1","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce afecțiuni sau condiții locale și de tranziție sunt recunoscute drept factori etiologici în apariția ocluziei deschise anterioare?","options":[{"id":"A","text":"Ocluzia deschisă de tranziție se manifestă în erupția dinților permanenți și beneficiază de corecție spontană prin remodelare alveolară."},{"id":"B","text":"Afecțiunile reumatice la nivelul articulației temporo-mandibulare ce induc poziții antalgice ale condilului în cavitatea glenoidă."},{"id":"C","text":"Tulburările de erupție caracterizate de anchiloza dinților laterali sunt incriminate ca principal factor în ocluzia deschisă frontală asimetrică."},{"id":"D","text":"Obiceiul de interpoziție digitală este considerat normal în cursul dezvoltării până în jurul vârstei de 5-6 ani."},{"id":"E","text":"Formațiunile limfoepiteliale ale orofaringelui reprezintă o patologie scheletică ce devine evidentă doar la sfârșitul perioadei de creștere."}],"correct":["A","B","D"],"pages":[512],"source":"set-2"},{"id":"set2-TTY-ohgf","fingerprint":"b738cddfa7657684","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la mecanismul etiopatogenic al rahitismului în dezvoltarea ocluziei deschise?","options":[{"id":"A","text":"Se produce o rotație anterioară a maxilarului și o rotație posterioară a mandibulei."},{"id":"B","text":"Oasele maxilare, devenind maleabile pe fondul calcifierii defectuoase, se deformează mai ușor sub acțiunea forțelor musculare."},{"id":"C","text":"Mușchii coborâtori ai mandibulei tracționează mandibula în sus și înainte, fiind mai puternici decât cei ridicători."},{"id":"D","text":"Se produce o deformare antegoniană a ramului orizontal al mandibulei, însoțită de oblicitatea accentuată a acestuia."},{"id":"E","text":"Are loc o închidere a unghiului mandibular, având drept consecință micșorarea etajului inferior al feței."}],"correct":["A","B","D"],"pages":[514],"source":"set-2"},{"id":"set2-RV8yjnRc","fingerprint":"a91139f2cce4cced","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Ce caracteristici sunt asociate factorului genetic în etiopatogenia ocluziei deschise?","options":[{"id":"A","text":"Deficiențele în dezvoltarea verticală apar din cauza compensării reciproce optime între tiparul erupției dentare și direcția procesului de creștere."},{"id":"B","text":"Pacienții cu tipar de creștere orizontal sunt mai predispuși la a dezvolta ocluzie deschisă comparativ cu cei cu tipar vertical."},{"id":"C","text":"Tiparul facial hiperdivergent permite erupția verticală a molarilor, determinând un model scheletal vertical excesiv."},{"id":"D","text":"Ocluzia deschisă este asociată cu sindroame genetice precum disostoza cleido-craniană, sindromul Down și sindromul Treacher-Collins."},{"id":"E","text":"Controlul dimensiunilor sagitale, transversale și verticale, precum și direcțiile de creștere, sunt atribuite terenului genetic."}],"correct":["C","D","E"],"pages":[514],"source":"set-2"},{"id":"set2-JxVYjWrF","fingerprint":"2853279e158b57ea","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect tulburările funcționale implicate în etiologia ocluziei deschise?","options":[{"id":"A","text":"Deglutiția infantilă devine o deglutiție anormală după erupția dinților temporari, când funcția ar trebui să se realizeze cu arcadele dentare în contact și limba poziționată în interiorul acestora."},{"id":"B","text":"Inocluzia verticală se instalează din cauza inhibării procesului de căutare a antagonistului, fenomen determinat de interpoziția limbii."},{"id":"C","text":"Interpoziția limbii între arcade în cadrul deglutiției infantile stimulează procesul de căutare a antagonistului."},{"id":"D","text":"Deglutiția de tip infantil este considerată o funcție normală dacă persistă după erupția dinților temporari."},{"id":"E","text":"Persistența deglutiției viscerale după erupția dinților temporari determină inocluzie verticală."}],"correct":["A","B","E"],"pages":[514],"source":"set-2"},{"id":"set2-m0nOpY2X","fingerprint":"1a47cb5e47d68ae1","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt efectele factorului dismetabolic, manifestat prin perturbarea metabolismului fosfo-calcic în primul an de viață, asupra aparatului dento-maxilar?","options":[{"id":"A","text":"Crește rezistența bazelor osoase, limitând rotația diferențiată a maxilarelor."},{"id":"B","text":"Dinții pot prezenta hipoplazii, hipocalcificări, precum și modificări coronare și radiculare."},{"id":"C","text":"Generează o plasticitate osoasă crescută care face structura scheletică vulnerabilă la acțiunea presiunilor funcționale."},{"id":"D","text":"Provoacă deformări caracteristice exclusiv la nivelul bolții palatine, lăsând arcadele dentare intacte."},{"id":"E","text":"Creează un decalaj osos major între baze, care nu poate fi compensat prin dezvoltare dento-alveolară."}],"correct":["B","C","E"],"pages":[514],"source":"set-2"},{"id":"set2-SaXHCjov","fingerprint":"30878f945c7edb18","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații definesc rolul genei MMP9, frecvent asociată cu ocluzia deschisă anterioară?","options":[{"id":"A","text":"Joacă un rol cheie în organogeneză și în procesul de creștere prin degradarea extracelulară a matricei proteice."},{"id":"B","text":"Codifică sinteza unei enzime implicate în degradarea enzimatică intracelulară a matricei proteice."},{"id":"C","text":"Mutațiile acesteia determină de sine stătător un model scheletal orizontal hiperdivergent."},{"id":"D","text":"Controlează exclusiv dezvoltarea sagitală a proceselor alveolare superioare."},{"id":"E","text":"Codifică sinteza unei metaloproteinaze matriceale implicate în procesele de modelare și remodelare osoasă."}],"correct":["A","E"],"pages":[514],"source":"set-2"},{"id":"set2-UbBlpNOp","fingerprint":"9c2fd04771f75d62","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele caracteristici definește precis ocluzia deschisă produsă prin obiceiul vicios de succiune a degetului?","options":[{"id":"A","text":"Ocluzia deschisă rezultată este, în majoritatea cazurilor, asimetrică."},{"id":"B","text":"Severitatea anomaliei depinde exclusiv de forța fizică exercitată, fiind independentă de vârsta pacientului."},{"id":"C","text":"Efectul exclusiv al acestui obicei constă în denivelarea planului de ocluzie, fără a produce deformări ale arcadelor."},{"id":"D","text":"Forma dezvoltată a ocluziei deschise este, de cele mai multe ori, perfect simetrică."},{"id":"E","text":"Severitatea anomaliei devine clinic semnificativă doar dacă obiceiul depășește 12 ore pe zi."}],"correct":["A"],"pages":[515],"source":"set-2"},{"id":"set2-p0aOuXur","fingerprint":"9881bf3d9678ccea","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afecțiuni sistemice pot induce degenerare condiliană la nivelul articulației temporo-mandibulare, cu apariția secundară a ocluziei deschise?","options":[{"id":"A","text":"Artritele localizate la nivelul regiunii frontale a mandibulei."},{"id":"B","text":"Sclerodermia"},{"id":"C","text":"Resorbția idiopatică a condilului mandibular, manifestată predominant la pacienți de sex masculin."},{"id":"D","text":"Sindromul Sjögren"},{"id":"E","text":"Spondilita anchilozantă"}],"correct":["B","D","E"],"pages":[516],"source":"set-2"},{"id":"set2-5RKrF21e","fingerprint":"4e6687a8c039ade5","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Referitor la anomaliile de poziție și volum ale limbii (macroglosia) implicate în etiopatogenia ocluziei deschise, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Poziționarea anterioară și joasă a limbii favorizează în mod direct dezvoltarea maxilarului superior."},{"id":"B","text":"Asocierea macroglosiei cu o poziție nefavorabilă a limbii crește exclusiv probabilitatea instalării ocluziei deschise parțiale."},{"id":"C","text":"Poziția joasă a limbii împiedică contactul interarcadic frontal, determinând infrapoziția dinților anteriori."},{"id":"D","text":"Macroglosia influențează poziția dinților, determinând vestibularizarea acestora."},{"id":"E","text":"Marginile laterale ale limbii prezintă frecvent amprenta dinților laterali în prezența macroglosiei."}],"correct":["C","D","E"],"pages":[516],"source":"set-2"},{"id":"set2-kK2GiBLc","fingerprint":"b3cc764051998420","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"În contextul patogeniei ocluziei deschise, care sunt caracteristicile tulburărilor de deglutiție implicate în dezvoltarea acestei anomalii?","options":[{"id":"A","text":"Deglutiția de tip infantil este denumită în literatura de specialitate și deglutiție „viscerală”."},{"id":"B","text":"Persistența deglutiției infantile determină inocluzie verticală prin inhibarea procesului de căutare a antagonistului."},{"id":"C","text":"Interpoziția limbii între arcade este mecanismul principal care generează inhibarea procesului de căutare a antagonistului."},{"id":"D","text":"Toate ipotezele științifice confirmă faptul că deglutiția infantilă este în mod exclusiv cauza ocluziei deschise anterioare."},{"id":"E","text":"Deglutiția de tip adult presupune realizarea funcției fără contactul arcadelor dentare, limba fiind interpusă între acestea."}],"correct":["A","B","C"],"pages":[514],"source":"set-2"},{"id":"set2-st0IoelV","fingerprint":"0e48232fd0d8df18","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele tipuri de traumatisme sau fracturi sunt responsabile de apariția inocluziei verticale în regiunea frontală, ca urmare a generării unor contacte premature la nivelul dinților posteriori?","options":[{"id":"A","text":"Fracturile care interesează ramul mandibular și fracturile tip Le Fort I"},{"id":"B","text":"Fracturile simfizare mandibulare izolate"},{"id":"C","text":"Forțele traumatice exercitate asupra dentiției temporare"},{"id":"D","text":"Traumatismele condiliene suferite în perioada de creștere"},{"id":"E","text":"Fracturile maxilare de tip Le Fort II"}],"correct":["A"],"pages":[516],"source":"set-2"},{"id":"set2-lf2MgZBz","fingerprint":"eb331172cc6a7f2d","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următorii factori iatrogeni, de erupție sau de tratament pot contribui la instalarea sau agravarea ocluziei deschise?","options":[{"id":"A","text":"Tratamentele ortodontice instituite ca necesitate terapeutică limitată sau ca incident terapeutic."},{"id":"B","text":"Primele stadii ale tratamentului ortodontic cu aparate dentare fixe, care produc exclusiv efecte favorabile asupra dinților și oaselor maxilare."},{"id":"C","text":"Obturațiile și lucrările protetice supradimensionate ocluzal."},{"id":"D","text":"Erupția molarilor de minte, în special la pacienții care prezintă o supraacoperire frontală majoră (ocluzie adâncă)."},{"id":"E","text":"Reincluzia molarului de 6 ani."}],"correct":["A","C","E"],"pages":[517],"source":"set-2"},{"id":"set2-mLPli0II","fingerprint":"eb558d8c82551cac","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt semnele clinice faciale întâlnite în ocluzia deschisă totală?","options":[{"id":"A","text":"Procheilia superioară"},{"id":"B","text":"Profilul facial accentuat concav"},{"id":"C","text":"Scurtarea ramului ascendent al mandibulei"},{"id":"D","text":"Șanțul labio-mentonier șters"},{"id":"E","text":"Fanta labială deschisă, cu vizibilitatea incisivilor superiori în repaus"}],"correct":["A","C","D"],"pages":[517],"source":"set-2"},{"id":"set2-9NViktsp","fingerprint":"fcda72b3e79f5868","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele unghiuri, evaluat pe teleradiografia de profil, are o valoare normală de 22º-25º și deține valoare prognostică în evoluția ocluziei deschise?","options":[{"id":"A","text":"Unghiul Tweed"},{"id":"B","text":"Unghiul antegonial"},{"id":"C","text":"Unghiul mandibular"},{"id":"D","text":"Unghiul condilian"},{"id":"E","text":"Unghiul B a lui Schwarz"}],"correct":["A"],"pages":[518],"source":"set-2"},{"id":"set2-om1cCH3h","fingerprint":"459d352c32b5cafc","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele modificări reprezintă semne clinice intraorale considerate patognomonice pentru etiologia dismetabolică a ocluziei deschise?","options":[{"id":"A","text":"Infradenția anterioară asociată cu denivelarea planului de ocluzie"},{"id":"B","text":"Displaziile de smalț"},{"id":"C","text":"Inversarea raportului de mărime între molarii de 12 ani și cei de 6 ani"},{"id":"D","text":"Orientarea incisivilor inferiori în linie dreaptă"},{"id":"E","text":"Volumul redus la nivelul coroanelor dentare"}],"correct":["B","D"],"pages":[518],"source":"set-2"},{"id":"set2-kd8y53BE","fingerprint":"6817f6d2c96d1f2d","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt modificările radiologice specifice evidențiate în ocluzia deschisă gravă?","options":[{"id":"A","text":"Raportul dintre înălțimea posterioară și înălțimea anterioară facială mai mic de 0,65"},{"id":"B","text":"Reducerea înălțimii verticale a ramului ascendent mandibular"},{"id":"C","text":"Rotația anterioară a mandibulei în sens invers acelor de ceasornic"},{"id":"D","text":"Suprapoziția incisivilor și infrapoziția molarilor"},{"id":"E","text":"Oblicitatea accentuată a ramului orizontal al mandibulei"}],"correct":["A","B","E"],"pages":[518],"source":"set-2"},{"id":"set2-GPU5mai6","fingerprint":"29491dc45902bbfe","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele entități determină un spațiu de inocluzie verticală cu care se realizează diagnosticul diferențial al ocluziei deschise?","options":[{"id":"A","text":"Macroglosia cu dezvoltarea unei atrezii mandibulare"},{"id":"B","text":"Reincluzia dentară"},{"id":"C","text":"Perioada erupției dentare"},{"id":"D","text":"Necesitatea terapeutică pentru asigurarea saltului articular"},{"id":"E","text":"Incluzia dentară a caninilor superiori"}],"correct":["B","C","D"],"pages":[519],"source":"set-2"},{"id":"set2-34sEQbl_","fingerprint":"329b3c52632e7fac","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele reprezintă consecințe funcționale ale ocluziei deschise asupra aparatului dento-maxilar?","options":[{"id":"A","text":"Reducerea eficienței masticatorii prin imposibilitatea inciziei și triturării alimentelor"},{"id":"B","text":"Incontinența salivară manifestată cu precădere în timpul masticației"},{"id":"C","text":"Apariția respirației orale ca urmare a fantei labiale deschise și a boltei palatine adânci"},{"id":"D","text":"Vorbirea cu interpoziția limbii între arcade în timpul pronunțării fonemelor dentale"},{"id":"E","text":"Afectarea parodonțiului la nivelul dinților aflați în supraocluzie prin forțe masticatorii reduse"}],"correct":["A","C","D"],"pages":[519],"source":"set-2"},{"id":"set2-Dy3deriq","fingerprint":"66b3bb4dbbb9872c","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următorii factori influențează în cea mai mare măsură prognosticul ocluziei deschise?","options":[{"id":"A","text":"Vârsta la care a fost depistată anomalia."},{"id":"B","text":"Timpul erupției primului molar permanent."},{"id":"C","text":"Factorii cauzali implicați."},{"id":"D","text":"Asocierea sa la alte anomalii dento-maxilare."},{"id":"E","text":"Momentul instituirii tratamentului ortodontic."}],"correct":["A","C","D","E"],"pages":[520],"source":"set-2"},{"id":"set2-rjuUPWs7","fingerprint":"b8c72a029f212ed2","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect influența anomaliilor dento-maxilare asociate asupra conduitei terapeutice și prognosticului ocluziei deschise?","options":[{"id":"A","text":"Corectarea prodenției în cadrul asocierii cu compresiunea de maxilar determină creșterea spațiului de inocluzie verticală."},{"id":"B","text":"Conduita terapeutică în prognatismul mandibular asociat este dictată de o creștere deficitară a mandibulei."},{"id":"C","text":"Cazurile determinate de factori genetici sunt mai receptive la tratament comparativ cu cele cu determinism local."},{"id":"D","text":"Asocierea cu prognatismul mandibular adevărat constituie un factor agravant."},{"id":"E","text":"Asocierea cu compresiunea de maxilar reprezintă o situație favorabilă tratamentului ortodontic."}],"correct":["D","E"],"pages":[520],"source":"set-2"},{"id":"set2-hWOQWU_e","fingerprint":"d67fd85125837841","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care sunt obiectivele terapeutice principale ale tratamentului ocluziei deschise?","options":[{"id":"A","text":"Echilibrarea relațiilor de ocluzie, cu precădere în plan vertical."},{"id":"B","text":"Echilibrarea relațiilor de ocluzie, cu precădere în plan sagital."},{"id":"C","text":"Normalizarea funcțiilor aparatului dento-maxilar."},{"id":"D","text":"Menținerea constantă a inocluziei verticale pentru a permite adaptarea musculară."},{"id":"E","text":"Armonizarea dezvoltării arcadelor alveolo-dentare."}],"correct":["A","C","E"],"pages":[520],"source":"set-2"},{"id":"set2-LJk-9low","fingerprint":"b7b1c25bbb5bf492","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CS","text":"Care dintre următoarele afirmații reflectă particularitățile generale și de abordare terapeutică în ocluzia deschisă?","options":[{"id":"A","text":"Tratamentul ocluziei deschise este ușor de gestionat, având o rată minimă de recidivă independent de abordare."},{"id":"B","text":"Decizia privind tratamentul ortodontico-chirurgical este guvernată exclusiv de funcțiile aparatului dento-maxilar și ignoră etiologia bolii."},{"id":"C","text":"Particularitățile proceselor de creștere și dezvoltare individuale sunt irelevante pentru stabilirea planului curativ."},{"id":"D","text":"Ocluziile deschise determinate în principal de factorii locali sunt mai receptive la tratament decât cazurile cu determinare genetică."},{"id":"E","text":"Un diagnostic incorect generează un proces de compensare naturală cu remiterea parțială a afecțiunii."}],"correct":["D"],"pages":[520],"source":"set-2"},{"id":"set2-WpWhij87","fingerprint":"d8af553e67f1c3c2","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații referitoare la tratamentul profilactico-preventiv al ocluziei deschise sunt corecte?","options":[{"id":"A","text":"Profilaxia sau tratamentul rahitismului reprezintă o componentă a tratamentului profilactico-preventiv, aplicată începând imediat după naștere."},{"id":"B","text":"Reeducarea funcției respiratorii se instituie imediat după îndepărtarea chirurgicală a obstacolelor de la nivelul căilor aeriene superioare."},{"id":"C","text":"Reeducarea funcției de deglutiție este indicat a se realiza anterior decondiționării obiceiurilor vicioase de interpoziție."},{"id":"D","text":"Se consideră că obiceiurile vicioase nu pot produce modificări ireversibile la nivelul aparatului dento-maxilar până la vârsta de 5-6 ani."},{"id":"E","text":"Terapia prin exerciții specifice deglutiției nu poate fi combinată cu tratamentul ortodontic activ prin aparate cu scut lingual."}],"correct":["A","B","D"],"pages":[520],"source":"set-2"},{"id":"set2-PNQgKXvd","fingerprint":"00ed5d7cf296070c","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"În ceea ce privește tratamentul ortodontic curativ și tardiv al ocluziei deschise, care dintre următoarele aspecte sunt adevărate?","options":[{"id":"A","text":"În tratamentul ortodontic tardiv, compensarea decalajului scheletal mandibulo-maxilar se realizează eficient exclusiv prin mijloace ortodontice."},{"id":"B","text":"Tratamentul curativ poate utiliza aparate ortodontice mobilizabile ancorate pe gutiere, aparate funcționale sau aparate fixe poliagregate."},{"id":"C","text":"Intervenția curativă precoce este justificată de potențialul de recidivă mult mai mare care apare după diminuarea sau finalizarea proceselor de creștere, în special după vârsta de 20 de ani."},{"id":"D","text":"Corectarea inocluziei verticale se realizează predominant prin asigurarea posibilității ingresiunii dinților din zona de inocluzie verticală."},{"id":"E","text":"Creșterea duratei tratamentului ortodontic activ în terapia tardivă determină o reducere proporțională a perioadei de contenție."}],"correct":["B","C"],"pages":[521],"source":"set-2"},{"id":"set2-4uFAdGGX","fingerprint":"7c3c68cc14c05d6e","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect obiectivele și particularitățile terapiei interceptive în ocluzia deschisă?","options":[{"id":"A","text":"Presupune corectarea decalajului oaselor maxilare doar după erupția completă a dentiției definitive și finalizarea creșterii."},{"id":"B","text":"Apreciată de unii specialiști ca etapă inițială obligatorie, terapia interceptivă poate reduce semnificativ durata tratamentului ortodontic activ în formele grave."},{"id":"C","text":"Limitarea acțiunii factorilor cauzali de la debut poate asigura erupția dentară în parametri normali, făcând uneori inutilă intervenția ortodontică ulterioară."},{"id":"D","text":"Eliminarea factorilor cauzali prin terapie interceptivă împiedică reluarea proceselor de creștere, necesitând obligatoriu intervenție chirurgicală."},{"id":"E","text":"Are ca scop surprinderea semnelor clinice incipiente și limitarea modificărilor asupra aparatului dento-maxilar."}],"correct":["B","C","E"],"pages":[521],"source":"set-2"},{"id":"set2-aRpvG1oW","fingerprint":"0bf40bdb8b3a3367","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următorii factori și parametri caracterizează faza de contenție și riscul de recidivă post-terapeutică în ocluzia deschisă?","options":[{"id":"A","text":"Datorită potențialului mare de recidivă, ocluzia deschisă impune monitorizare ulterioară prin controale periodice."},{"id":"B","text":"Ocluzia deschisă este caracterizată printr-un răspuns facil la tratament și o stabilitate crescută pe termen lung."},{"id":"C","text":"Durata contenției trebuie să fie cel mult jumătate din durata perioadei de tratament activ."},{"id":"D","text":"Prezența molarilor de minte este recunoscută ca un factor care crește riscul de recidivă a ocluziei deschise."},{"id":"E","text":"Durata perioadei de contenție trebuie să fie cel puțin egală cu durata perioadei de tratament activ."}],"correct":["A","D","E"],"pages":[521],"source":"set-2"},{"id":"set2-zyKditvx","fingerprint":"f24275ea5cd8412e","chapterId":"set-2","subchapterId":"set2-6.2.3","type":"CM","text":"Care dintre următoarele aspecte sunt corecte referitor la tulburările funcționale și abordarea lor în etiopatogenia ocluziei deschise?","options":[{"id":"A","text":"În prezența respirației orale, reeducarea funcției respiratorii precede întotdeauna eliberarea pasajului aerian de obstacolele superioare."},{"id":"B","text":"Tratamentul profilactico-preventiv al tulburărilor de fonație se inițiază doar după finalizarea creșterii, în jurul vârstei de 20 de ani."},{"id":"C","text":"Exercițiile specifice pentru reeducarea funcției de deglutiție trebuie să vizeze conștientizarea poziției limbii exclusiv în timpul actului de deglutiție."},{"id":"D","text":"Reușita terapeutică presupune înțelegerea felului în care factorii cauzatori funcționali interrelaționează și se potențează reciproc."},{"id":"E","text":"Reeducarea funcției de deglutiție implică o succesiune de etape cu exerciții practicate zilnic în prize repetate."}],"correct":["D","E"],"pages":[520],"source":"set-2"}];
